// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/proxy/beacon/UpgradeableBeacon.sol";

/**
 * @title MyBeacon
 * @dev Beacon contract that stores the implementation address
 * Multiple BeaconProxy contracts can point to this beacon
 */
contract MyBeacon is UpgradeableBeacon {
    constructor(address implementation_, address initialOwner) UpgradeableBeacon(implementation_, initialOwner) {}
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/proxy/beacon/BeaconProxy.sol";

/**
 * @title MyBeaconProxy
 * @dev Beacon Proxy that delegates calls to the implementation pointed by the beacon
 */
contract MyBeaconProxy is BeaconProxy {
    constructor(address beacon, bytes memory data) BeaconProxy(beacon, data) {}
}

