        __ERC721_init(name_, symbol_);
        __ERC721URIStorage_init();
        __Ownable_init(initialOwner);
        maxSupply = maxSupply_;
        mintPrice = mintPrice_;
    }

    function mint(address to, string memory uri) external payable returns (uint256) {
        require(_nextTokenId < maxSupply, "NFTCollection: max supply reached");
        require(msg.value >= mintPrice, "NFTCollection: insufficient payment");

        uint256 tokenId = _nextTokenId++;
        _safeMint(to, tokenId);
        _setTokenURI(tokenId, uri);

        emit NFTMinted(to, tokenId, uri);
        return tokenId;
    }

    function ownerMint(address to, string memory uri) external onlyOwner returns (uint256) {
        require(_nextTokenId < maxSupply, "NFTCollection: max supply reached");

        uint256 tokenId = _nextTokenId++;
        _safeMint(to, tokenId);
        _setTokenURI(tokenId, uri);

        emit NFTMinted(to, tokenId, uri);
        return tokenId;
    }

    function totalMinted() external view returns (uint256) {
        return _nextTokenId;
    }

    function withdraw() external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "NFTCollection: no balance to withdraw");
        (bool success, ) = owner().call{value: balance}("");
        require(success, "NFTCollection: withdrawal failed");
    }

    // Required overrides
    function tokenURI(uint256 tokenId) public view override(ERC721Upgradeable, ERC721URIStorageUpgradeable) returns (string memory) {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(bytes4 interfaceId) public view override(ERC721Upgradeable, ERC721URIStorageUpgradeable) returns (bool) {
